<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Computer Languages Quiz</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #080d18;
      --panel: #111827;
      --panel-strong: #172033;
      --text: #f8fafc;
      --muted: #bac7d8;
      --accent: #7dd3fc;
      --accent-strong: #38bdf8;
      --border: #334155;
      --success: #86efac;
      --error: #fca5a5;
      --shadow: 0 24px 60px rgba(0, 0, 0, 0.38);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-width: 320px;
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      line-height: 1.5;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(56, 189, 248, 0.22), transparent 34rem),
        radial-gradient(circle at bottom right, rgba(129, 140, 248, 0.18), transparent 32rem),
        var(--bg);
    }

    .skip-link {
      position: absolute;
      top: 0.75rem;
      left: 0.75rem;
      z-index: 10;
      padding: 0.75rem 1rem;
      color: #06111f;
      background: var(--accent);
      border-radius: 999px;
      transform: translateY(-150%);
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 3px solid var(--text);
      outline-offset: 3px;
    }

    main {
      width: min(100% - 2rem, 58rem);
      margin: 0 auto;
      padding: 3rem 0;
    }

    .quiz-shell {
      padding: clamp(1.25rem, 4vw, 2.5rem);
      background: linear-gradient(145deg, rgba(17, 24, 39, 0.96), rgba(15, 23, 42, 0.9));
      border: 1px solid rgba(148, 163, 184, 0.24);
      border-radius: 1.5rem;
      box-shadow: var(--shadow);
    }

    .eyebrow {
      margin: 0 0 0.5rem;
      color: var(--accent);
      font-size: 0.875rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 8vw, 4rem);
      line-height: 1;
      letter-spacing: -0.06em;
    }

    .intro {
      max-width: 44rem;
      margin: 1rem 0 2rem;
      color: var(--muted);
      font-size: 1.0625rem;
    }

    form {
      display: grid;
      gap: 1.25rem;
    }

    .form-field {
      padding: clamp(1rem, 3vw, 1.5rem);
      background: rgba(15, 23, 42, 0.78);
      border: 1px solid var(--border);
      border-radius: 1.125rem;
    }

    fieldset {
      min-inline-size: 0;
      margin: 0;
      padding: 0;
      border: 0;
    }

    legend {
      width: 100%;
      margin-bottom: 0.75rem;
      padding: 0;
      color: var(--text);
      font-size: 1.125rem;
      font-weight: 800;
    }

    .help-text {
      margin: -0.25rem 0 1rem;
      color: var(--muted);
    }

    .choices {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(13rem, 1fr));
      gap: 0.75rem;
    }

    .choice {
      display: flex;
      align-items: flex-start;
      gap: 0.75rem;
      min-height: 3.5rem;
      padding: 0.875rem;
      color: var(--text);
      background: var(--panel-strong);
      border: 1px solid rgba(148, 163, 184, 0.24);
      border-radius: 0.875rem;
      cursor: pointer;
      transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
    }

    .choice:hover {
      border-color: var(--accent-strong);
      background: #1d2a40;
      transform: translateY(-1px);
    }

    input[type="checkbox"] {
      flex: 0 0 auto;
      width: 1.25rem;
      height: 1.25rem;
      margin: 0.15rem 0 0;
      accent-color: var(--accent-strong);
    }

    input[type="checkbox"]:focus-visible,
    button:focus-visible {
      outline: 3px solid var(--accent);
      outline-offset: 4px;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 1rem;
      margin-top: 0.5rem;
    }

    button {
      min-height: 2.75rem;
      padding: 0.85rem 1.25rem;
      color: #04111f;
      font: inherit;
      font-weight: 800;
      background: linear-gradient(135deg, var(--accent), var(--accent-strong));
      border: 0;
      border-radius: 999px;
      box-shadow: 0 12px 24px rgba(56, 189, 248, 0.22);
      cursor: pointer;
    }

    button:hover {
      background: linear-gradient(135deg, #bae6fd, var(--accent));
    }

    .status {
      min-height: 1.5rem;
      margin: 0;
      color: var(--success);
      font-weight: 700;
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
      }
    }

    @media (forced-colors: active) {
      .quiz-shell,
      .form-field,
      .choice,
      button {
        border: 1px solid CanvasText;
        box-shadow: none;
      }

      button {
        color: ButtonText;
        background: ButtonFace;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to main content</a>

  <main id="main">
    <div class="quiz-shell">
      <p class="eyebrow">Multi-select quiz</p>
      <h1>Computer Languages</h1>
      <p class="intro">Choose every answer that applies for each question, then submit your responses.</p>

      <div id="quiz-root"></div>
    </div>
  </main>

  <script>
    const quizQuestions = [
      {
        id: "q1",
        name: "programming-languages",
        prompt: "Which of these are programming languages?",
        helpText: "Select all options that are used to write executable software.",
        choices: ["Python", "JavaScript", "HTML", "C#"],
        correctAnswers: ["Python", "JavaScript", "C#"]
      },
      {
        id: "q2",
        name: "browser-languages",
        prompt: "Which languages are commonly used to build browser apps?",
        choices: ["JavaScript", "TypeScript", "Python", "SQL"],
        correctAnswers: ["JavaScript", "TypeScript"]
      },
      {
        id: "q3",
        name: "statically-typed",
        prompt: "Which languages are statically typed by default?",
        choices: ["Java", "Go", "Ruby", "Rust"],
        correctAnswers: ["Java", "Go", "Rust"]
      }
    ];

    function ChoiceOption({ questionId, name, choice }) {
      const id = `${questionId}-${choice.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;

      return `
        <label class="choice" for="${id}">
          <input id="${id}" name="${name}" type="checkbox" value="${choice}">
          <span>${choice}</span>
        </label>
      `;
    }

    function QuestionField({ question, index }) {
      const describedBy = question.helpText ? ` aria-describedby="${question.id}-help"` : "";
      const helpText = question.helpText
        ? `<p id="${question.id}-help" class="help-text">${question.helpText}</p>`
        : "";
      const choices = question.choices
        .map(choice => ChoiceOption({ questionId: question.id, name: question.name, choice }))
        .join("");

      return `
        <div class="form-field">
          <fieldset${describedBy}>
            <legend>${index + 1}. ${question.prompt}</legend>
            ${helpText}
            <div class="choices">
              ${choices}
            </div>
          </fieldset>
        </div>
      `;
    }

    function QuizApp({ questions }) {
      const questionFields = questions
        .map((question, index) => QuestionField({ question, index }))
        .join("");

      return `
        <form id="quiz-form" novalidate>
          ${questionFields}
          <div class="actions">
            <button type="submit">Submit quiz</button>
            <p id="quiz-status" class="status" aria-live="polite"></p>
          </div>
        </form>
      `;
    }

    function selectedValues(form, name) {
      return Array.from(form.querySelectorAll(`input[name="${name}"]:checked`), checkbox => checkbox.value);
    }

    function arraysMatch(first, second) {
      return first.length === second.length && first.every(value => second.includes(value));
    }

    document.getElementById("quiz-root").innerHTML = QuizApp({ questions: quizQuestions });

    document.getElementById("quiz-form").addEventListener("submit", event => {
      event.preventDefault();

      const form = event.currentTarget;
      const score = quizQuestions.reduce((total, question) => {
        const selected = selectedValues(form, question.name);
        return total + (arraysMatch(selected, question.correctAnswers) ? 1 : 0);
      }, 0);

      document.getElementById("quiz-status").textContent = `You scored ${score} out of ${quizQuestions.length}.`;
    });
  </script>
</body>
</html>
