         name: "programming-languages",
         prompt: "Which of these are programming languages?",
         helpText: "Select all options that are used to write executable software.",
         choices: ["Python", "JavaScript", "HTML", "C#"],
         correctAnswers: ["Python", "JavaScript", "C#"]
       },
       {
         id: "q2",
         name: "browser-languages",
         prompt: "Which languages are commonly used to build browser apps?",
         choices: ["JavaScript", "TypeScript", "Python", "SQL"],
         correctAnswers: ["JavaScript", "TypeScript"]
       },
       {
         id: "q3",
         name: "statically-typed",
         prompt: "Which languages are statically typed by default?",
         choices: ["Java", "Go", "Ruby", "Rust"],
         correctAnswers: ["Java", "Go", "Rust"]
       }
     ];

     function ChoiceOption({ questionId, name, choice }) {
       const id = `${questionId}-${choice.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;

       return `
         <label class="choice" for="${id}">
           <input id="${id}" name="${name}" type="checkbox" value="${choice}">
           <span>${choice}</span>
         </label>
       `;
     }

     function QuestionField({ question, index }) {
       const describedBy = question.helpText ? ` aria-describedby="${question.id}-help"` : "";
       const helpText = question.helpText
         ? `<p id="${question.id}-help" class="help-text">${question.helpText}</p>`
         : "";
       const choices = question.choices
         .map(choice => ChoiceOption({ questionId: question.id, name: question.name, choice }))
         .join("");

       return `
         <div class="form-field">
           <fieldset${describedBy}>
             <legend>${index + 1}. ${question.prompt}</legend>
             ${helpText}
             <div class="choices">
               ${choices}
             </div>
           </fieldset>
         </div>
       `;
     }

     function QuizApp({ questions }) {
       const questionFields = questions
         .map((question, index) => QuestionField({ question, index }))
         .join("");

       return `
         <form id="quiz-form" novalidate>
           ${questionFields}
           <div class="actions">
             <button type="submit">Submit quiz</button>
             <p id="quiz-status" class="status" aria-live="polite"></p>
           </div>
         </form>
       `;
     }

     function selectedValues(form, name) {
       return Array.from(form.querySelectorAll(`input[name="${name}"]:checked`), checkbox => checkbox.value);
     }

     function arraysMatch(first, second) {
       return first.length === second.length && first.every(value => second.includes(value));
     }

     document.getElementById("quiz-root").innerHTML = QuizApp({ questions: quizQuestions });

     document.getElementById("quiz-form").addEventListener("submit", event => {
       event.preventDefault();

       const form = event.currentTarget;
       const score = quizQuestions.reduce((total, question) => {
         const selected = selectedValues(form, question.name);
         return total + (arraysMatch(selected, question.correctAnswers) ? 1 : 0);
       }, 0);

       document.getElementById("quiz-status").textContent = `You scored ${score} out of ${quizQuestions.length}.`;
     });
   </script>
